from pathlib import Path
import html,re,difflib,json
import markdown
OUT=Path(__file__).resolve().parent;ROOT=OUT.parents[3]
def render(s,prefix):
 s=re.sub(r'<!--\s*@[^>]*-->','',s)
 return markdown.markdown(s,extensions=['extra','sane_lists']).replace('id="fn','id="'+prefix+'-fn').replace('href="#fn','href="#'+prefix+'-fn')
def photo(name,caption):
 return '<figure><a href="'+name+'.png"><img src="'+name+'.png" alt="'+html.escape(caption,quote=True)+'"></a><figcaption>'+caption+'</figcaption></figure>'
before=(OUT/'Trans_Body.before.md').read_text(encoding='utf-8');after=(OUT/'Trans_Body.after.md').read_text(encoding='utf-8');assert after==(ROOT/'commons/maps/Trans_Body/final.md').read_text(encoding='utf-8')
a,b=before.split('\n\n'),after.split('\n\n');pairs=[]
for i,(tag,x,y,u,v) in enumerate(difflib.SequenceMatcher(None,a,b,autojunk=False).get_opcodes()):
 if tag=='equal':continue
 left=render('\n\n'.join(a[x:y]),'old-'+str(i)) or '<p>New illustration.</p>';right=render('\n\n'.join(b[u:v]),'new-'+str(i)) or '<p>Passage removed.</p>'
 pairs.append('<div class="pair"><div><h4>Before</h4>'+left+'</div><div><h4>Now</h4>'+right+'</div></div>')
css=re.search(r'<style>(.*?)</style>',(OUT.parent/'2026-09-23-transformation-encounters/index.html').read_text(encoding='utf-8'),re.S)[1]
css+=' .pair img{max-width:100%} .reading{margin-top:25px} figure img{height:auto} .triptych{display:grid;grid-template-columns:repeat(3,1fr);gap:18px}.triptych figure{margin:0}.triptych figcaption{font-size:14px}@media(max-width:850px){.triptych{grid-template-columns:1fr}}'
page='<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Body — what does the room keep?</title><style>'+css+'</style></head><body><main>'
page+='''<div class="eyebrow">Ada Research / Trans Body / 23 September 2026</div><h1>What does the room keep?</h1><div class="intro"><p>The slats close. The blocks regain their size. The lattice keeps the cut.</p><p>Some of you passed above the entire record.</p></div><p class="status">Applied to <strong>Trans_Body/final.md</strong>. The existing encounters remain; a construction repair keeps the shrinking blocks on the floor. The before/after lattice image is also in the book.</p><nav><a href="#encounter">Working illustration</a><a href="#responses">Three responses</a><a href="#comparison">Text differences</a><a href="#reading">Read the hall</a><a href="SUMMARY.md">Scope and evidence</a><a href="/compose/sources?map=Trans_Body&amp;doc=final">Comment on final.md</a></nav>'''
page+='<section id="encounter"><h2>A passage the next body inherits</h2>'+photo('the-cut-remains','The same elevated camera before and after a supplied walk by the actual museum body. Its collision shape is 0.64 m wide and 1.5 m high. The walk removed 132 of 484 cells; the body is outside the lattice in the second picture.')+'<p>The cut records a collision shape, an added reach and a grid resolution. The low block never enclosed the visitor’s whole body.</p></section>'
page+='<section id="responses"><h2>Approach, cross, leave</h2><details><summary>Slats and blocks: what returns</summary><h3>The wall turns</h3><div class="triptych">'+photo('slats-before','Before the approach.')+photo('slats-near','The approaching body opens a run of slats.')+photo('slats-after','After crossing and leaving reach, the wall closes.')+'</div><h3>The blocks shrink</h3><div class="triptych">'+photo('blocks-before','Full size, on the deck.')+photo('blocks-near','Neighbouring blocks become smaller as the body walks between them.')+photo('blocks-after','After the body leaves reach, all nine regain their size.')+'</div></details><details><summary>The small repair the images exposed</summary><p>The first run showed that affected blocks rose 0.575 m off the floor when they changed size. Physics had retained their initial centre before automatic grounding moved the artifact. Seeding the correct standing height before adding each block to the scene fixes the mismatch. Dimensions, sensing and the scale law are unchanged.</p><p>All nine bases now remain on the deck before, during and after their response; mesh and collision agree. The actual museum body walks through the field after this repair.</p><p><a href="block-seating-before.json">Measured defect</a> · <a href="source-changes.diff">Exact repair and documentation changes</a></p></details></section>'
page+='''<section id="comparison"><h2>The body was already involved</h2><p>The chapter keeps all three encounters and code excerpts. The distance explanation reads in a clearer order, the carving margin becomes an account of pressing forward, and the closing return remembers the cube ride and bottle. The opening, partial-body record and question about who fits the cut remain.</p><details open><summary>Original and revised passages</summary>'''+''.join(pairs)+'''</details><p><a href="Trans_Body.diff">Exact manuscript diff</a></p></section>'''
page+='<section id="reading"><h2>Trans Body</h2><article class="reading">'+render(after,'reading')+'</article></section>'
page+='''<footer><p>Eighty focused checks pass in the isolated actual museum, including five selected walking segments through the three thresholds and nine-block grounding/mesh/collision comparisons. The existing standalone body-response regression also passes. The probe supplies walking input and places the body at each separate approach; this is not a full human traversal or headset test.</p><p>Next: The Moving Boundary (Trans_Pit), where a clock changes the room even when the visitor stands still.</p><p><a href="report.json">Runtime checks</a> · <a href="standalone-regression.txt">Standalone regression</a> · <a href="verification.json">Publication checks</a> · <a href="SUMMARY.md">Scope</a></p></footer></main></body></html>'''
(OUT/'index.html').write_text(page,encoding='utf-8');print(OUT/'index.html')
